function validate([start, target]) {
  if (typeof start !== 'string' || typeof target !== 'string') return 'start and target must be strings.';
  if (start.length !== target.length) return 'start and target must have the same length.';
  if (start.length < 1 || start.length > 100000) return 'The strings need 1 to 100000 characters.';
  if (!/^[LR_]+$/.test(start) || !/^[LR_]+$/.test(target)) return "Use only 'L', 'R' and '_'.";
  return null;
}

