  const n = start.length;
  let i = 0;
  let j = 0;

  while (i < n || j < n) {
    while (i < n && start[i] === '_') {
      i++;
    }
    while (j < n && target[j] === '_') {
      j++;
    }
    if (i === n || j === n) {
      return i === n && j === n;
    }
    if (start[i] !== target[j]) {
      return false;
    }
    if (start[i] === 'L' && j > i) {
      return false;
    }
    if (start[i] === 'R' && j < i) {
      return false;
    }
    i++;
    j++;
  }
  return true;
}

