function canChange(start, target) {
  // Breadth-first search over every board reachable from start.
  const seen = new Set([start]);
  const queue = [start];
  for (let head = 0; head < queue.length; head++) {
    const board = queue[head];
    if (board === target) return true;
    for (let p = 0; p < board.length; p++) {
      let next = null;
      if (board[p] === 'L' && p > 0 && board[p - 1] === '_') next = board.slice(0, p - 1) + 'L_' + board.slice(p + 1);
      if (board[p] === 'R' && p + 1 < board.length && board[p + 1] === '_') next = board.slice(0, p) + '_R' + board.slice(p + 2);
      if (next !== null && !seen.has(next)) {
        seen.add(next);
        queue.push(next);
      }
    }
  }
  return false;
}

