function generate(rand, size) {
  const n = size === 'large' ? 5000 + Math.floor(rand() * 4001) : 1 + Math.floor(rand() * 9);
  const pick = () => '_LR'[Math.floor(rand() * 3)];
  const mode = rand();
  if (mode < 0.15) {
    // Two unrelated boards.
    return [Array.from({ length: n }, pick).join(''), Array.from({ length: n }, pick).join('')];
  }
  // Build a reachable pair: pieces keep their order, L never moves right, R never moves left.
  const start = new Array(n).fill('_');
  const target = new Array(n).fill('_');
  const spread = size === 'large' ? 4 : 3;
  let prevStart = -1;
  let prevTarget = -1;
  for (;;) {
    const piece = rand() < 0.5 ? 'L' : 'R';
    let from, to;
    if (piece === 'L') {
      to = prevTarget + 1 + Math.floor(rand() * spread);
      from = Math.max(to, prevStart + 1) + Math.floor(rand() * spread);
    } else {
      from = prevStart + 1 + Math.floor(rand() * spread);
      to = Math.max(from, prevTarget + 1) + Math.floor(rand() * spread);
    }
    if (from >= n || to >= n) break;
    start[from] = piece;
    target[to] = piece;
    prevStart = from;
    prevTarget = to;
  }
  if (mode < 0.55) return [start.join(''), target.join('')];
  if (mode < 0.8) {
    // Spoil one cell of the target; this usually breaks reachability.
    target[Math.floor(rand() * n)] = pick();
    return [start.join(''), target.join('')];
  }
  // Swap the roles, so pieces would have to move the wrong way.
  return [target.join(''), start.join('')];
}
